class Televisao:
    def __init__(self, min_canal=2, max_canal=14):
        self.ligada = False
        self.cmin = min_canal
        self.cmax = max_canal
        self.canal = min_canal

    def muda_canal_para_baixo(self):
        if self.canal - 1 >= self.cmin:
            self.canal -= 1
        else:
            print(f"Limite inferior atingido! Canal mínimo é {self.cmin}.")

tv = Televisao(min_canal=2, max_canal=14)
tv.muda_canal_para_baixo()  # Não deve diminuir abaixo de 2
print(f"Canal atual: {tv.canal}")  # 2

