class Televisao:
    def __init__(self, min_canal=2, max_canal=14):
        self.ligada = False
        self.cmin = min_canal
        self.cmax = max_canal
        self.canal = min_canal

    def muda_canal_para_cima(self):
        if self.canal + 1 <= self.cmax:
            self.canal += 1
        else:
            print(f"Limite superior atingido! Canal máximo é {self.cmax}.")

tv = Televisao(min_canal=2, max_canal=5)
tv.canal = 5
tv.muda_canal_para_cima()  # Não deve ultrapassar 5
print(f"Canal atual: {tv.canal}")  # 5

