class Conta:
    def __init__(self, titular, numero, saldo=0.0):
        self.titular = titular
        self.numero = numero
        self.saldo = saldo

    def pode_sacar(self, valor):
        return self.saldo >= valor

    def saque(self, valor):
        if self.pode_sacar(valor):
            self.saldo -= valor
            return True
        return False

class ContaEspecial(Conta):
    def __init__(self, titular, numero, saldo=0.0, limite=1000.0):
        super().__init__(titular, numero, saldo)
        self.limite = limite

    def pode_sacar(self, valor):
        return (self.saldo + self.limite) >= valor

c_comum = Conta("Marcos", 1, 100)
print(c_comum.saque(150))  # False (Saldo insuficiente)

c_esp = ContaEspecial("Lia", 2, 100, 500)
print(c_esp.saque(150))    # True (Aprovado pelo limite de crédito)

