class Conta:
    def __init__(self, titular, numero, saldo=0.0):
        self.titular = titular
        self.numero = numero
        self.saldo = saldo
        self.operacoes = []

    def pode_sacar(self, valor):
        return self.saldo >= valor

    def saque(self, valor):
        if self.pode_sacar(valor):
            self.saldo -= valor
            self.operacoes.append(["SAQUE", valor])
            return True
        return False

class ContaEspecial(Conta):
    def __init__(self, titular, numero, saldo=0.0, limite=500.0):
        super().__init__(titular, numero, saldo)
        self.limite = limite

    def pode_sacar(self, valor):
        return (self.saldo + self.limite) >= valor

# ContaEspecial NÃO redefine saque(), mas herda e funciona polimorficamente!
ce = ContaEspecial("Paulo", 303, saldo=100.0, limite=400.0)
print(ce.saque(350.0))  # True! (Saldo passa a ser -250.0)
print(ce.saldo)         # -250.0
